        .instructions-list li {
            display: flex;
            align-items: flex-start;
            gap: 0.75rem;
            padding: 0.75rem 0;
            color: var(--gray-700);
            font-size: 0.95rem;
            line-height: 1.6;
        }

        .instruction-number {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 28px;
            height: 28px;
            background: var(--red-500);
            color: white;
            border-radius: 50%;
            font-weight: 700;
            font-size: 0.875rem;
            flex-shrink: 0;
        }

        .instruction-text {
            padding-top: 0.2rem;
        }

