/* NWCA Production Schedule — modern aesthetic
   Light warm canvas, single teal accent, Geist Sans + Geist Mono.
   No Inter / Roboto / system gradients.
*/

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  font-family: Geist, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Helvetica Neue", sans-serif;
  font-size: 14px;
  line-height: 1.45;
  color: var(--c-fg);
  background: var(--c-bg);
  font-feature-settings: "ss01", "ss02", "cv11";
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizelegibility;
}

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --production-shifts-gray-dark: #333;
    --production-shifts-yellow-dark: #4a3a10;
    --production-shifts-indigo-dark: #2e1f4d;

  /* surfaces */
  --c-bg:        oklch(98.5% 0.004 90deg);
  --c-surface:   var(--color-surface);
  --c-surface-2: oklch(97.5% 0.005 90deg);
  --c-border:    oklch(92% 0.005 90deg);
  --c-border-strong: oklch(86% 0.005 90deg);

  /* text */
  --c-fg:        oklch(22% 0.01 270deg);
  --c-fg-muted:  oklch(50% 0.01 270deg);
  --c-fg-soft:   oklch(68% 0.01 270deg);

  /* accent — confident teal-green */
  --c-accent:    oklch(55% 0.13 175deg);
  --c-accent-fg: var(--color-surface);
  --c-accent-soft: oklch(93% 0.04 175deg);

  /* status — same chroma, varied hue */
  --c-work:      oklch(62% 0.14 155deg);
  --c-work-bg:   oklch(94% 0.05 155deg);
  --c-break:     oklch(68% 0.13 75deg);
  --c-break-bg:  oklch(95% 0.06 80deg);
  --c-lunch:     oklch(60% 0.14 290deg);
  --c-lunch-bg:  oklch(94% 0.05 290deg);
  --c-off:       oklch(72% 0.01 270deg);
  --c-off-bg:    oklch(95% 0.003 270deg);
  --c-pre:       oklch(72% 0.01 270deg);
  --c-pre-bg:    oklch(95% 0.003 270deg);

  /* sizing */
  --label-w: 200px;
  --row-h: 56px;
  --radius: 10px;
  --shadow-sm: 0 1px 2px rgb(20 30 40 / 4%);
  --shadow-md: 0 4px 14px rgb(20 30 40 / 6%), 0 1px 3px rgb(20 30 40 / 4%);
  --shadow-lg: 0 12px 40px rgb(20 30 40 / 12%), 0 2px 8px rgb(20 30 40 / 4%);
}
/* stylelint-enable color-no-hex */

button { font-family: inherit; cursor: pointer; }

/* ============================================================
   APP shell
   ============================================================ */
.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.main {
  padding: 24px 32px 64px;
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ============================================================
   Top bar
   ============================================================ */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 32px;
  border-bottom: 1px solid var(--c-border);
  background: color-mix(in oklab, var(--c-surface) 70%, transparent);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 20;
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 36px; height: 36px;
  border-radius: 8px;
  background: var(--c-accent);
  color: var(--c-accent-fg);
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-sm);
}

.brand-line {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-fg-muted);
  font-weight: 500;
}

.page-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.effective-date {
  margin-top: 2px;
  font-size: 11.5px;
  color: var(--c-fg-muted);
  font-feature-settings: "tnum";
}

/* ============================================================
   Breadcrumb (non-sticky strip above the topbar)
   ============================================================ */
.ps-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 32px;
  font-size: 13px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface-2);
}

.ps-breadcrumb a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--c-fg-muted);
  text-decoration: none;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
}

.ps-breadcrumb a:hover {
  background: var(--c-surface);
  color: var(--c-accent);
}

.ps-breadcrumb-sep {
  color: var(--c-fg-soft);
  font-size: 14px;
}

.ps-breadcrumb-current {
  color: var(--c-fg);
  font-weight: 600;
  padding: 4px 8px;
}

@media (width <= 720px) {
  .ps-breadcrumb { padding: 8px 16px; font-size: 12px; }
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.date-block {
  text-align: right;
  margin-right: 8px;
}

.date-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-fg-muted);
}

.date-value {
  font-size: 13px;
  font-weight: 600;
}

.btn-ghost, .btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 500;
  border: 1px solid var(--c-border);
  background: var(--c-surface);
  color: var(--c-fg);
  transition: background 0.15s, border-color 0.15s;
}

.btn-ghost:hover {
  background: var(--c-surface-2);
  border-color: var(--c-border-strong);
}

.btn-primary {
  background: var(--c-accent);
  color: var(--c-accent-fg);
  border-color: var(--c-accent);
}

.btn-primary:hover {
  filter: brightness(1.05);
}

.btn-small {
  padding: 5px 9px;
  font-size: 12px;
}

/* ============================================================
   Compliance notice banners
   ============================================================ */
.notices {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

@media (width <= 1100px) {
  .notices { grid-template-columns: 1fr; }
}

.notice {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 16px;
  border-radius: var(--radius);
  background: oklch(97% 0.04 80deg);
  border: 1px solid oklch(85% 0.08 80deg);
  color: oklch(30% 0.07 75deg);
}

.notice-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: oklch(94% 0.08 80deg);
  color: oklch(45% 0.13 75deg);
  flex-shrink: 0;
}
.notice-body { flex: 1; min-width: 0; }

.notice-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(45% 0.13 75deg);
  font-weight: 600;
  margin-bottom: 2px;
}

.notice-text {
  font-size: 13.5px;
  font-weight: 500;
  color: var(--c-fg);
  line-height: 1.4;
}

.notice-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
  color: oklch(40% 0.12 75deg);
  text-decoration: none;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid oklch(80% 0.10 80deg);
  background: var(--c-surface);
  flex-shrink: 0;
  transition: background 0.15s;
}
.notice-link:hover { background: oklch(95% 0.04 80deg); }

/* Policy notice — warmer red-orange to distinguish from law */
.notice-policy {
  background: oklch(96% 0.04 35deg);
  border-color: oklch(83% 0.10 35deg);
  color: oklch(32% 0.10 30deg);
}

.notice-policy .notice-icon {
  background: oklch(93% 0.10 35deg);
  color: oklch(47% 0.16 30deg);
}
.notice-policy .notice-label { color: oklch(47% 0.16 30deg); }

/* Schedule notice — calm teal to distinguish from law (amber) and policy (red) */
.notice-schedule {
  background: oklch(96% 0.04 200deg);
  border-color: oklch(83% 0.08 200deg);
  color: oklch(30% 0.08 200deg);
}

.notice-schedule .notice-icon {
  background: oklch(93% 0.08 200deg);
  color: oklch(45% 0.13 200deg);
}
.notice-schedule .notice-label { color: oklch(45% 0.13 200deg); }

/* ============================================================
   Waiver download card — prominent action CTA
   ============================================================ */
.waiver-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, oklch(96% 0.05 280deg), oklch(97% 0.04 260deg));
  border: 1px solid oklch(80% 0.10 280deg);
  color: oklch(30% 0.10 280deg);
  text-decoration: none;
  transition: transform 0.15s, box-shadow 0.15s, border-color 0.15s;
}

.waiver-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px oklch(30% 0.10 280deg / 12%);
  border-color: oklch(65% 0.14 280deg);
}

.waiver-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: oklch(92% 0.10 280deg);
  color: oklch(45% 0.16 280deg);
  flex-shrink: 0;
}

.waiver-body {
  flex: 1;
  min-width: 0;
}

.waiver-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(45% 0.16 280deg);
  font-weight: 600;
  margin-bottom: 2px;
}

.waiver-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--c-fg);
  letter-spacing: -0.01em;
  margin-bottom: 2px;
}

.waiver-sub {
  font-size: 13px;
  color: var(--c-fg-muted);
  line-height: 1.4;
}

.waiver-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: oklch(40% 0.16 280deg);
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid oklch(70% 0.14 280deg);
  background: var(--c-surface);
  flex-shrink: 0;
}

.waiver-card:hover .waiver-cta {
  background: oklch(94% 0.06 280deg);
}

@media (width <= 720px) {
  .waiver-card { flex-wrap: wrap; }
  .waiver-cta { width: 100%; justify-content: center; }
}

/* Waiver disclaimer — visually attached below the waiver card */
.waiver-note {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: -24px;
  padding: 12px 18px;
  border-radius: 0 0 var(--radius) var(--radius);
  background: oklch(97% 0.04 80deg);
  border: 1px solid oklch(85% 0.08 80deg);
  border-top: none;
  color: oklch(32% 0.07 75deg);
  font-size: 12.5px;
  line-height: 1.45;
}

.waiver-note-icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: oklch(50% 0.16 75deg);
  margin-top: 1px;
}
.waiver-note strong { font-weight: 600; }

/* ============================================================
   Day summary row
   ============================================================ */
.stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.stat-card {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: var(--shadow-sm);
}

.stat-num {
  font-size: 36px;
  font-weight: 600;
  letter-spacing: -0.03em;
  font-feature-settings: "tnum";
  line-height: 1;
  color: var(--c-fg);
  font-family: Geist, ui-sans-serif, sans-serif;
}

.stat-card .stat-num {
  /* if value is a time string, switch to mono */
}

.stat-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-fg);
  margin-top: 6px;
}

.stat-sub {
  font-size: 12px;
  color: var(--c-fg);
  font-weight: 500;
}

/* ============================================================
   Status dots & pills
   ============================================================ */
.dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}
.dot-work  { background: var(--c-work); }
.dot-break { background: var(--c-break); }
.dot-lunch { background: var(--c-lunch); }
.dot-off   { background: var(--c-off); }
.dot-pre   { background: var(--c-pre); }

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  color: var(--c-fg);
  white-space: nowrap;
}

.pill-compact {
  padding: 3px 8px 3px 6px;
  font-size: 11px;
}
.pill-work  { background: var(--c-work-bg);  border-color: color-mix(in oklab, var(--c-work) 25%, transparent); }
.pill-break { background: var(--c-break-bg); border-color: color-mix(in oklab, var(--c-break) 25%, transparent); }
.pill-lunch { background: var(--c-lunch-bg); border-color: color-mix(in oklab, var(--c-lunch) 25%, transparent); }
.pill-off   { background: var(--c-off-bg);   border-color: color-mix(in oklab, var(--c-off) 25%, transparent); }
.pill-pre   { background: var(--c-pre-bg);   border-color: color-mix(in oklab, var(--c-pre) 25%, transparent); }

/* ============================================================
   Chip row (department filter)
   ============================================================ */
.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.chip-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-fg-muted);
  margin-right: 8px;
  font-weight: 500;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 6px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  color: var(--c-fg-muted);
  transition: all 0.15s;
}

.chip:hover {
  border-color: var(--c-border-strong);
  color: var(--c-fg);
}

.chip-active {
  background: var(--c-fg);
  border-color: var(--c-fg);
  color: var(--c-bg);
}

.chip-count {
  font-size: 11px;
  font-feature-settings: "tnum";
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--c-surface-2);
  color: var(--c-fg-muted);
  font-weight: 500;
}

.chip-active .chip-count {
  background: rgb(255 255 255 / 18%);
  color: var(--c-bg);
}

/* ============================================================
   Avatar
   ============================================================ */
.avatar {
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-weight: 600;
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

/* ============================================================
   Timeline card
   ============================================================ */
.timeline-card {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.timeline-head {
  padding: 20px 24px 16px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--c-border);
}

.timeline-head h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.timeline-head p {
  margin: 0;
  font-size: 12px;
  color: var(--c-fg-muted);
}

.timeline-head-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--c-fg-muted);
}

.legend-sw {
  width: 14px;
  height: 10px;
  border-radius: 4px;
  display: inline-block;
}
.legend-work  { background: var(--c-work); }
.legend-break { background: var(--c-break); }
.legend-lunch { background: var(--c-lunch); }

.now-readout {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  border-radius: 999px;
  background: var(--c-accent-soft);
  color: color-mix(in oklab, var(--c-accent) 80%, black);
  font-size: 12px;
  font-weight: 500;
}

.now-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--c-accent);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--c-accent) 40%, transparent);
  animation: pulse 2.5s ease-out infinite;
}
.now-dot.scrubbing { animation: none; background: var(--c-fg-muted); }

@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 color-mix(in oklab, var(--c-accent) 50%, transparent); }
  70%  { box-shadow: 0 0 0 8px color-mix(in oklab, var(--c-accent) 0%, transparent); }
  100% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--c-accent) 0%, transparent); }
}

.now-label {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 10px;
}

.now-time {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-weight: 600;
  font-size: 13px;
}

/* ---- timeline grid layout ---- */
.timeline-scroll {
  overflow-x: auto;
}

.timeline-grid {
  display: grid;
  grid-template-columns: var(--label-w) 1fr;
  min-width: 900px;
  position: relative;
}

/* hour axis */
.tl-axis-label { background: var(--c-surface-2); border-right: 1px solid var(--c-border); border-bottom: 1px solid var(--c-border); }

.tl-axis {
  position: relative;
  height: 32px;
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
  cursor: pointer;
}

.tl-tick {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
}

.tl-tick-label {
  position: absolute;
  top: 9px;
  left: 4px;
  font-size: 11px;
  font-family: "Geist Mono", ui-monospace, monospace;
  color: var(--c-fg-muted);
  font-weight: 500;
}

/* row label (left column) */
.tl-row-label {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  height: var(--row-h);
  border-right: 1px solid var(--c-border);
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface);
  text-align: left;
  border-top: none;
  border-left: none;
  transition: background 0.12s;
}
.tl-row-label:hover { background: var(--c-surface-2); }
.tl-row-label.selected { background: var(--c-accent-soft); }
.tl-row-meta { min-width: 0; }

.tl-row-name {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tl-row-role {
  font-size: 11px;
  color: var(--c-fg-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* row rail (right column) */
.tl-row {
  position: relative;
  height: var(--row-h);
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface);
}
.tl-row.selected { background: color-mix(in oklab, var(--c-accent-soft) 50%, transparent); }

.tl-gridline {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--c-border);
  opacity: 0.55;
}

/* shift envelope — faint container behind segments */
.tl-envelope {
  position: absolute;
  top: 12px;
  bottom: 12px;
  background: var(--c-surface-2);
  border-radius: 999px;
  border: 1px dashed color-mix(in oklab, var(--c-border-strong) 60%, transparent);
}

/* segments */
.tl-seg {
  position: absolute;
  top: 14px;
  bottom: 14px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--c-bg);
  cursor: pointer;
  transition: filter 0.15s, transform 0.12s;
  overflow: hidden;
}
.tl-seg:hover { filter: brightness(0.95); }
.tl-seg-work  { background: var(--c-work);  }
.tl-seg-break { background: var(--c-break); color: oklch(25% 0.07 75deg); }
.tl-seg-lunch { background: var(--c-lunch); }
.tl-seg-label { padding: 0 8px; }

/* shift caps with mini time labels */
.tl-cap {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.tl-cap .cap-time {
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  font-family: "Geist Mono", ui-monospace, monospace;
  color: var(--c-fg-muted);
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.15s;
}

.tl-row:hover .tl-cap .cap-time,
.tl-row.selected .tl-cap .cap-time { opacity: 1; }

/* playhead — absolutely positioned over the rail column */
.tl-playhead-col {
  position: absolute;
  inset: 0 0 0 var(--label-w);
  pointer-events: none;
  z-index: 6;
}

.tl-playhead {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--c-accent);
}
.tl-playhead.scrubbing { background: var(--c-fg); }

.tl-playhead::before {
  content: "";
  position: absolute;
  top: 38px;  /* just below the axis bar */
  left: 50%;
  transform: translateX(-50%);
  width: 10px; height: 10px;
  background: inherit;
  border-radius: 50%;
  border: 2px solid var(--c-surface);
  box-shadow: 0 0 0 1px var(--c-accent);
}
.tl-playhead.scrubbing::before { box-shadow: 0 0 0 1px var(--c-fg); }

.tl-playhead-flag {
  position: absolute;
  top: 4px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--c-accent);
  color: var(--c-accent-fg);
  padding: 3px 8px;
  border-radius: 6px;
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  z-index: 2;
}

.tl-playhead.scrubbing .tl-playhead-flag {
  background: var(--c-fg);
}

/* scrubber */
.timeline-foot {
  padding: 16px 24px 24px;
  border-top: 1px solid var(--c-border);
  background: var(--c-surface-2);
  position: relative;
}

.tl-scrubber {
  appearance: none;
  width: 100%;
  height: 4px;
  background: var(--c-border-strong);
  border-radius: 999px;
  outline: none;
}

.tl-scrubber::-webkit-slider-thumb {
  appearance: none;
  width: 18px; height: 18px;
  background: var(--c-fg);
  border: 3px solid var(--c-surface);
  border-radius: 50%;
  box-shadow: 0 1px 4px rgb(0 0 0 / 15%);
  cursor: grab;
}

.tl-scrubber::-moz-range-thumb {
  width: 18px; height: 18px;
  background: var(--c-fg);
  border: 3px solid var(--c-surface);
  border-radius: 50%;
  cursor: grab;
}

.scrubber-ticks {
  position: relative;
  height: 16px;
  margin-top: 6px;
}

.scrubber-tick-label {
  position: absolute;
  transform: translateX(-50%);
  font-size: 10px;
  font-family: "Geist Mono", ui-monospace, monospace;
  color: var(--c-fg-muted);
}

/* ============================================================
   Roster
   ============================================================ */
.roster {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.roster-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.roster-head h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.roster-count {
  font-size: 12px;
  color: var(--c-fg-muted);
  font-feature-settings: "tnum";
}

.roster-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 10px;
}

.roster-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px 16px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  text-align: left;
  transition: all 0.15s;
  box-shadow: var(--shadow-sm);
  font-family: inherit;
}

.roster-card:hover {
  border-color: var(--c-border-strong);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.roster-card.selected {
  border-color: var(--c-accent);
  box-shadow: 0 0 0 3px var(--c-accent-soft);
}

.roster-card-top {
  display: flex;
  align-items: center;
  gap: 12px;
}
.roster-card-meta { flex: 1; min-width: 0; }

.roster-name {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.005em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.roster-role {
  font-size: 11px;
  color: var(--c-fg-muted);
  margin-top: 2px;
}

.roster-hrs {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  font-feature-settings: "tnum";
  color: var(--c-fg);
  display: flex;
  align-items: baseline;
  gap: 3px;
  flex-shrink: 0;
}

.roster-hrs span {
  font-size: 11px;
  color: var(--c-fg-muted);
  font-weight: 500;
}

.roster-card-bottom {
  display: grid;
  grid-template-columns: 1.6fr 1.3fr 1fr;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--c-border);
}

.roster-cell-label {
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--c-fg-muted);
  margin-bottom: 3px;
  font-weight: 500;
}

.roster-cell-val {
  font-size: 12.5px;
  color: var(--c-fg);
}

.mono {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-feature-settings: "tnum";
}

/* ============================================================
   Detail panel (slide-over)
   ============================================================ */
.scrim {
  position: fixed;
  inset: 0;
  background: rgb(20 30 40 / 18%);
  backdrop-filter: blur(2px);
  z-index: 30;
  animation: fade 0.18s ease;
}

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

.detail-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(440px, 100%);
  background: var(--c-surface);
  border-left: 1px solid var(--c-border);
  box-shadow: var(--shadow-lg);
  padding: 24px 28px;
  z-index: 40;
  overflow-y: auto;
  animation: slidein 0.22s cubic-bezier(0.2, 0.7, 0.2, 1);
}

@keyframes slidein {
  from { transform: translateX(20px); opacity: 0; }
  to   { transform: translateX(0); opacity: 1; }
}

.detail-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px; height: 32px;
  border-radius: 8px;
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-fg-muted);
  display: grid;
  place-items: center;
  transition: background 0.15s;
}

.detail-close:hover {
  background: var(--c-surface-2);
  color: var(--c-fg);
}

.detail-head {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
  padding-right: 40px;
}

.detail-name {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.detail-role {
  font-size: 12px;
  color: var(--c-fg-muted);
}

.detail-status {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}

.detail-paid {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 12px;
  color: var(--c-fg-muted);
  padding: 4px 10px;
  background: var(--c-surface-2);
  border-radius: 999px;
}

.detail-note {
  font-size: 12px;
  color: var(--c-fg-muted);
  padding: 10px 12px;
  background: var(--c-surface-2);
  border-radius: 8px;
  margin-bottom: 24px;
  line-height: 1.5;
}

.detail-timeline {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
}

.evt {
  display: grid;
  grid-template-columns: 110px 16px 1fr;
  gap: 14px;
  align-items: flex-start;
  padding: 10px 0;
  position: relative;
}

.evt + .evt::before {
  content: "";
  position: absolute;
  left: 117px;
  top: -8px;
  bottom: calc(100% - 14px);
  width: 1px;
  background: var(--c-border);
}

.evt::after {
  content: "";
  position: absolute;
  left: 117px;
  top: 22px;
  bottom: -8px;
  width: 1px;
  background: var(--c-border);
}
.evt:last-child::after { display: none; }

.evt-time {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 12px;
  color: var(--c-fg-muted);
  text-align: right;
  padding-top: 1px;
}

.evt-dot {
  width: 12px; height: 12px;
  margin-top: 4px;
  border-radius: 50%;
  background: var(--c-fg);
  border: 2px solid var(--c-surface);
  outline: 1px solid var(--c-border-strong);
  position: relative;
  z-index: 2;
}

.evt-start .evt-dot,
.evt-end   .evt-dot { background: var(--c-fg); outline-color: var(--c-fg); }
.evt-break .evt-dot { background: var(--c-break); outline-color: var(--c-break); }
.evt-lunch .evt-dot { background: var(--c-lunch); outline-color: var(--c-lunch); }

.evt-label {
  font-size: 13px;
  color: var(--c-fg);
  padding-top: 0;
}

/* ============================================================
   Foot
   ============================================================ */
.page-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: var(--c-fg-soft);
  padding-top: 12px;
  border-top: 1px solid var(--c-border);
}

/* ============================================================
   Master schedule table
   ============================================================ */
.master-card {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.master-head {
  padding: 20px 24px 16px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--c-border);
}

.master-head h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.master-head p {
  margin: 0;
  font-size: 12px;
  color: var(--c-fg-muted);
}

.master-head-right {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.master-print {
  flex-shrink: 0;
}
.master-scroll { overflow-x: auto; }

.master-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  min-width: 880px;
}

.master-table thead th {
  text-align: left;
  padding: 12px 14px;
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
  color: var(--c-fg-muted);
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 600;
  white-space: nowrap;
}
.master-table thead th:not(.th-name, .th-role) { text-align: center; }

.master-table tbody tr {
  cursor: pointer;
  transition: background 0.1s;
}
.master-table tbody tr:hover { background: var(--c-surface-2); }
.master-table tbody tr.selected { background: var(--c-accent-soft); }

.master-table tbody td {
  padding: 12px 14px;
  border-bottom: 1px solid var(--c-border);
  vertical-align: middle;
}
.master-table tbody tr:last-child td { border-bottom: none; }

.td-name { font-weight: 600; color: var(--c-fg); white-space: nowrap; }
.td-name-wrap { display: flex; align-items: center; gap: 10px; }
.td-role { color: var(--c-fg-muted); font-size: 12.5px; white-space: nowrap; }

.td-paid {
  text-align: center;
  font-weight: 600;
  font-size: 14px;
  font-feature-settings: "tnum";
  color: var(--c-fg);
  white-space: nowrap;
}
.td-paid span { font-weight: 500; color: var(--c-fg-muted); font-size: 11px; }

/* Cell color coding (matches the legend & timeline) */
.cell { text-align: center; font-weight: 500; white-space: nowrap; }
.cell-clock { background: color-mix(in oklab, var(--c-accent-soft) 65%, transparent); color: var(--c-fg); }
.cell-break { background: var(--c-break-bg); color: oklch(32% 0.08 75deg); }
.cell-lunch { background: var(--c-lunch-bg); color: oklch(32% 0.08 290deg); font-weight: 600; }

.cell-sub {
  font-size: 10.5px;
  font-weight: 400;
  color: var(--c-fg-muted);
  margin-top: 2px;
  letter-spacing: 0;
  font-family: inherit;
}

.master-table tbody tr.selected .cell-clock,
.master-table tbody tr.selected .cell-break,
.master-table tbody tr.selected .cell-lunch { filter: brightness(0.97); }

/* Legend swatches */
.legend-clock { background: color-mix(in oklab, var(--c-accent) 60%, white); }

@media (width <= 880px) {
  .master-head { flex-direction: column; }
}

/* ============================================================
   Work Rules & Common Questions
   ============================================================ */
.workrules {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  padding: 28px 32px 24px;
  box-shadow: var(--shadow-sm);
  scroll-margin-top: 80px;
}

.wr-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.wr-card {
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.wr-card-featured {
  background: oklch(97% 0.04 80deg);
  border-color: oklch(85% 0.08 80deg);
  grid-column: span 2;
}

@media (width <= 880px) {
  .wr-card-featured { grid-column: auto; }
}

.wr-card-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.wr-card-eyebrow {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(45% 0.13 75deg);
  font-weight: 600;
  margin-bottom: 2px;
}

.wr-card-head h3 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--c-fg);
  letter-spacing: -0.005em;
  line-height: 1.25;
}

.wr-card ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.wr-card li {
  font-size: 13px;
  line-height: 1.5;
  color: var(--c-fg);
  position: relative;
  padding-left: 16px;
}

.wr-card li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--c-fg-muted);
}
.wr-card-featured li::before { background: oklch(55% 0.13 65deg); }

/* Loopholes block — bigger, redder warning */
.loopholes {
  background: oklch(97% 0.03 30deg);
  border: 1px solid oklch(82% 0.10 30deg);
  border-radius: var(--radius);
  padding: 22px 24px 20px;
}

.loopholes-head {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 18px;
}

.loopholes-icon {
  width: 38px; height: 38px;
  border-radius: 8px;
  background: oklch(92% 0.10 30deg);
  color: oklch(45% 0.18 30deg);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.loopholes-eyebrow {
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: oklch(45% 0.18 30deg);
  font-weight: 700;
  margin-bottom: 4px;
}

.loopholes-head h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--c-fg);
}

.loopholes-head p {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--c-fg-muted);
  max-width: 600px;
  line-height: 1.5;
}

.loopholes-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.loopholes-list li {
  background: var(--c-surface);
  border: 1px solid oklch(86% 0.06 30deg);
  border-radius: 8px;
  padding: 14px 16px;
}

.loophole-claim {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 6px;
}

.loophole-num {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: oklch(50% 0.18 30deg);
  color: var(--color-on-brand);
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  font-feature-settings: "tnum";
  flex-shrink: 0;
  margin-top: 1px;
}

.loophole-quote {
  font-size: 14px;
  font-weight: 600;
  color: var(--c-fg);
  font-style: italic;
}

.loophole-reality {
  font-size: 13px;
  line-height: 1.55;
  color: var(--c-fg);
  padding-left: 32px;
}

@media (width <= 600px) {
  .workrules { padding: 22px 18px; }
  .loopholes { padding: 18px 16px; }
  .loophole-reality { padding-left: 0; margin-top: 8px; }
}

/* ============================================================
   WA Labor Rules section
   ============================================================ */
.rules {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  padding: 28px 32px 24px;
  box-shadow: var(--shadow-sm);
  scroll-margin-top: 80px;
}
.rules-head { margin-bottom: 24px; }

.rules-eyebrow {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--c-accent);
  font-weight: 600;
  margin-bottom: 6px;
}

.rules-head h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--c-fg);
}

.rules-sub {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--c-fg-muted);
  max-width: 720px;
}

.rules-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

.rule-card {
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.rule-card-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rule-card-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--c-fg);
  letter-spacing: -0.005em;
}

.rule-icon {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: var(--c-accent-soft);
  color: color-mix(in oklab, var(--c-accent) 80%, black);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.rule-card ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.rule-card li {
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--c-fg);
  position: relative;
  padding-left: 16px;
}

.rule-card li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--c-fg-muted);
}

/* Verbatim statute disclosure */
.rules-source {
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  background: var(--c-surface);
  margin-bottom: 16px;
  overflow: hidden;
}

.rules-source summary {
  list-style: none;
  cursor: pointer;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  font-weight: 500;
  color: var(--c-fg);
  user-select: none;
}
.rules-source summary::-webkit-details-marker { display: none; }
.rules-source summary:hover { background: var(--c-surface-2); }

.src-eyebrow {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-fg-muted);
  font-weight: 600;
  padding: 3px 8px;
  background: var(--c-surface-2);
  border-radius: 999px;
  border: 1px solid var(--c-border);
}
.rules-source[open] summary { border-bottom: 1px solid var(--c-border); }

.chev {
  margin-left: auto;
  color: var(--c-fg-muted);
  transition: transform 0.2s;
}
.rules-source[open] .chev { transform: rotate(180deg); }

.wac-list {
  margin: 0;
  padding: 18px 22px 22px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--c-surface-2);
}

.wac-list li {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.wac-num {
  font-family: "Geist Mono", ui-monospace, monospace;
  font-size: 12px;
  color: var(--c-accent);
  font-weight: 600;
  padding-top: 1px;
  min-width: 24px;
}

.wac-list p {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--c-fg);
}

.rules-disclaimer {
  font-size: 11.5px;
  color: var(--c-fg-muted);
  font-style: italic;
  padding-top: 4px;
}

/* ============================================================
   Responsive
   ============================================================ */
@media (width <= 880px) {
  .topbar { padding: 12px 16px; }
  .main { padding: 16px 16px 48px; }
  .stat-row { grid-template-columns: repeat(2, 1fr); }
  :root { --label-w: 140px; }

  .topbar-right .btn-ghost,
  .topbar-right .btn-primary { display: none; }
}

@media (width <= 520px) {
  .stat-row { grid-template-columns: 1fr 1fr; gap: 8px; }
  .stat-num { font-size: 32px; }
}

/* ============================================================
   Print-only header (hidden on screen)
   ============================================================ */
.print-header { display: none; }

/* ============================================================
   Print stylesheet — master schedule only, clean PDF layout
   ============================================================ */
@media print {
  @page {
    size: letter landscape;
    margin: 0.35in 0.4in 0.4in;
  }

  /* color fidelity */
  * {
    -webkit-print-color-adjust: exact !important;
  }

  html, body {
    background: var(--color-surface) !important;
    font-size: 9pt;
  }

  /* Hide everything except the master schedule */
  .topbar,
  .stat-row,
  .chip-row,
  .timeline-card,
  .roster,
  .workrules,
  .rules,
  .page-foot,
  .scrim,
  .waiver-card,
  .waiver-note,
  .master-print,
  .ps-breadcrumb,
  .detail-panel { display: none !important; }

  /* Compact notice for print — keep visible because it's policy */
  .notice {
    padding: 5px 10px !important;
    border-width: 1px !important;
    border-radius: 4px !important;
    margin-bottom: 6px !important;
    gap: 8px !important;
    break-inside: avoid;
  }
  .notice-icon { width: 20px !important; height: 20px !important; border-radius: 4px !important; }
  .notice-icon svg { width: 12px !important; height: 12px !important; }
  .notice-label { font-size: 7pt !important; margin-bottom: 0 !important; }
  .notice-text { font-size: 9pt !important; line-height: 1.3 !important; }
  .notice-link { display: none !important; }

  .app { min-height: 0; }

  .main {
    padding: 0 !important;
    gap: 8px !important;
    max-width: none !important;
  }

  /* show the print-only header */
  .print-header {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding-bottom: 6px;
    margin-bottom: 6px;
    border-bottom: 1.5px solid var(--print-ink);
    break-inside: avoid;
  }

  .print-brand {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .print-brand-mark {
    width: 28px; height: 28px;
    border-radius: 6px;
    background: var(--c-accent);
    color: var(--color-on-brand);
    display: grid;
    place-items: center;
  }
  .print-brand-mark svg { width: 16px; height: 16px; }

  .print-eyebrow {
    font-size: 7.5pt;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--print-ink-soft);
    font-weight: 600;
    line-height: 1.2;
  }

  .print-title {
    margin: 0;
    font-size: 14pt;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--print-ink);
    line-height: 1.1;
  }

  .print-meta {
    text-align: right;
    font-size: 7.5pt;
    color: var(--production-shifts-gray-dark);
    line-height: 1.35;
    display: flex;
    flex-direction: column;
    gap: 1px;
  }

  .print-meta-row {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
  }
  .print-meta-row span { color: var(--gray-500); }
  .print-meta-row strong { color: var(--print-ink); font-weight: 600; min-width: 90px; text-align: right; }

  /* Master card — strip chrome, render flat, keep on one page */
  .master-card {
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    overflow: visible !important;
    background: transparent !important;
    break-inside: avoid;
  }

  .master-head {
    padding: 0 0 5px !important;
    border-bottom: 1px solid var(--gray-300) !important;
    margin-bottom: 4px;
    flex-direction: row !important;
    align-items: center !important;
    gap: 12px;
  }

  .master-head h2 {
    font-size: 11pt !important;
    color: var(--print-ink) !important;
    margin-bottom: 0 !important;
  }
  .master-head p { display: none !important; }

  .legend {
    gap: 10px;
    flex-shrink: 0;
  }

  .legend-item {
    font-size: 7.5pt;
    color: var(--production-shifts-gray-dark);
    gap: 4px;
  }

  .legend-sw {
    width: 11px;
    height: 8px;
    border: 1px solid rgb(0 0 0 / 8%);
  }

  .master-scroll { overflow: visible !important; }

  .master-table {
    width: 100%;
    min-width: 0 !important;
    font-size: 9pt;
    border: 1px solid var(--store-line);
    break-inside: avoid;
    border-collapse: collapse;
  }
  .master-table thead { display: table-header-group; }

  .master-table thead th {
    background: var(--gray-100) !important;
    color: var(--print-ink) !important;
    font-size: 7pt !important;
    padding: 5px 7px !important;
    border-bottom: 1px solid var(--print-line) !important;
    letter-spacing: 0.05em;
  }
  .master-table tbody tr { break-inside: avoid; }

  .master-table tbody tr:hover,
  .master-table tbody tr.selected { background: transparent !important; }

  .master-table tbody td {
    padding: 4px 7px !important;
    border-bottom: 1px solid var(--gray-200) !important;
    font-size: 9pt;
    line-height: 1.25;
  }
  .master-table tbody tr:last-child td { border-bottom: 1px solid var(--print-line) !important; }
  .td-name { color: var(--print-ink) !important; font-size: 9pt !important; }
  .td-name-wrap { gap: 7px !important; }
  .td-role { color: var(--gray-700) !important; font-size: 8.5pt !important; }
  .td-paid { color: var(--print-ink) !important; font-size: 10pt !important; }
  .td-paid span { color: var(--print-ink-soft) !important; font-size: 7.5pt !important; }

  .cell-clock { background: oklch(94% 0.04 175deg) !important; color: var(--print-ink) !important; }
  .cell-break { background: oklch(95% 0.06 80deg) !important; color: var(--production-shifts-yellow-dark) !important; }
  .cell-lunch { background: oklch(94% 0.05 290deg) !important; color: var(--production-shifts-indigo-dark) !important; font-weight: 600 !important; }
  .cell-sub { color: var(--print-ink-soft) !important; font-size: 7.5pt !important; margin-top: 1px !important; }

  /* smaller avatars to save vertical space */
  .td-name-wrap .avatar {
    width: 20px !important;
    height: 20px !important;
    font-size: 8px !important;
    background: var(--brand-100) !important;
    color: var(--production-shifts-gray-dark) !important;
  }

  .master-table tbody tr { cursor: default !important; }
}

/* 2026-09-05 review — keyboard path for master-table rows + visible focus */
.row-btn { background: none; border: 0; padding: 0; margin: 0; font: inherit; color: inherit; text-align: left; cursor: pointer; }

.row-btn:focus-visible, .chip:focus-visible, .roster-card:focus-visible, .tl-row-label:focus-visible,
.detail-close:focus-visible, .master-print:focus-visible, .btn-ghost:focus-visible, .waiver-card:focus-visible { outline: 2px solid currentcolor; outline-offset: 2px; }

/* Payroll — admin-only leave/hours dashboard. NWCA green theme; no inline styles. */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --payroll-gray: #5a665e;
    --payroll-green: #1a7c3a;
    --payroll-gray-2: #8a968f;
    --payroll-green-dark: #2c3b33;
    --payroll-gray-dark: #000;
    --payroll-orange: #8a5a10;
    --payroll-orange-2: #7a4f0d;
    --payroll-orange-3: #d9932a;
    --payroll-green-dark-2: #14682f;
    --payroll-orange-4: #7a4b06;
    --payroll-orange-5: #c77700;
}
/* stylelint-enable color-no-hex */

* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; background: var(--gray-100); color: var(--store-ink); }

.pr-wrap { max-width: 1240px; margin: 0 auto; padding: 1.5rem 1.25rem 4rem; }

.pr-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; border-bottom: 3px solid var(--brand-800); padding-bottom: 1rem; margin-bottom: 1rem; }
.pr-header h1 { color: var(--brand-800); font-size: 1.6rem; margin: 0; }
.pr-sub { color: var(--payroll-gray); margin: .35rem 0 0; font-size: .92rem; max-width: 72ch; }
.pr-back { color: var(--brand-mid); text-decoration: none; font-weight: 600; font-size: .9rem; white-space: nowrap; }
.pr-back:hover { color: var(--brand-800); }

.pr-status { min-height: 1.4rem; margin: .25rem 0 .75rem; font-size: .9rem; font-weight: 500; }
.pr-status.is-ok { color: var(--payroll-green); }
.pr-status.is-error { color: var(--red-700); }
.pr-status.is-info { color: var(--payroll-gray); }

.pr-tabs { display: flex; gap: .5rem; margin-bottom: 1rem; flex-wrap: wrap; }
.pr-tab { background: var(--store-green-100); border: none; color: var(--store-ink-soft); padding: .55rem 1.1rem; border-radius: 8px 8px 0 0; font-weight: 600; cursor: pointer; font-size: .95rem; }
.pr-tab.is-active { background: var(--brand-800); color: var(--color-on-brand); }

.pr-panel { display: none; background: var(--color-surface); border-radius: 10px; padding: 1.25rem; box-shadow: 0 1px 3px rgb(26 71 42 / 8%); }
.pr-panel.is-active { display: block; }
.pr-panel-head h2 { color: var(--brand-800); font-size: 1.15rem; margin: 0 0 .35rem; }
.pr-panel-head p { color: var(--payroll-gray); font-size: .9rem; margin: 0 0 1rem; max-width: 80ch; line-height: 1.5; }
.pr-h3 { color: var(--brand-800); font-size: 1rem; margin: 1.5rem 0 .6rem; }

.pr-toolbar { display: flex; align-items: center; gap: .75rem; margin-bottom: .9rem; flex-wrap: wrap; }
.pr-label { font-size: .88rem; font-weight: 600; color: var(--store-ink-soft); }
.pr-search, .pr-select { border: 1px solid var(--gray-300); border-radius: 7px; padding: .5rem .7rem; font-size: .92rem; font-family: inherit; color: var(--store-ink); background: var(--color-surface); }
.pr-search { min-width: 18rem; }
.pr-search:focus, .pr-select:focus { outline: 2px solid var(--brand-mid); outline-offset: 1px; }
.pr-asof { font-size: .85rem; color: var(--payroll-gray); margin-left: auto; }

/* Wide tables scroll inside their own container — the page never scrolls sideways. */
.pr-tablewrap { overflow-x: auto; }
.pr-table { width: 100%; border-collapse: collapse; font-size: .9rem; }
.pr-table th { text-align: left; background: var(--store-green-50); color: var(--payroll-green-dark); font-weight: 600; padding: .55rem .65rem; border-bottom: 2px solid var(--gray-300); white-space: nowrap; }

/* Spanning "Vacation"/"Sick" caption over their columns — see the two-row thead.
   Qualified with th so it outspecifies `.pr-table th { text-align: left }` above. */
.pr-table th.pr-group-head { text-align: center; font-size: .8rem; letter-spacing: .04em; text-transform: uppercase; color: var(--payroll-gray); border-bottom: 1px solid var(--gray-300); padding-bottom: .3rem; border-left: 1px solid var(--gray-300); }
.pr-table thead tr:first-child th { padding-bottom: .3rem; }
.pr-table thead tr:last-child th { padding-top: .3rem; }
.pr-table td { padding: .5rem .65rem; border-bottom: 1px solid var(--brand-100); white-space: nowrap; }
.pr-table tbody tr:hover { background: var(--gray-50); }
.pr-num { text-align: right; }
.pr-loading { color: var(--payroll-gray-2); font-style: italic; padding: 1rem .65rem; }

.pr-neg { color: var(--red-700); font-weight: 600; }
.pr-zero { color: var(--print-line); }
.pr-name { font-weight: 600; color: var(--store-ink); }
.pr-dept { color: var(--payroll-gray); }
.pr-pill { display: inline-block; font-size: .74rem; font-weight: 600; padding: .1rem .45rem; border-radius: 20px; background: var(--store-green-100); color: var(--store-ink-soft); margin-left: .4rem; }
.pr-pill-wait { background: var(--store-rush-soft); color: var(--payroll-orange); }
.pr-pill-flag { background: var(--store-rush-soft); color: var(--red-800); }
.pr-yes { color: var(--payroll-green); font-weight: 600; }
.pr-no { color: var(--print-line); }

/* --- carryover correction ------------------------------------------------
   The imported figure stays on screen next to the printed one, so the page can
   still be reconciled against the accountant's report at a glance. */
.pr-raw { color: var(--payroll-gray-2); text-decoration: line-through; }
.pr-arrow { color: var(--payroll-gray-2); margin: 0 .3rem; }
.pr-adj-demo { font-family: inherit; white-space: nowrap; color: var(--store-ink-soft); background: var(--store-green-50); border-radius: 4px; padding: 0 .3rem; }
.pr-entitle { color: var(--store-ink-soft); }

/* An unset entitlement is not zero — it blocks the slip, so it must not read as a number. */
.pr-missing { color: var(--red-700); font-weight: 600; font-size: .82rem; }
.pr-row-flag { background: var(--store-paper); }
.pr-row-flag:hover { background: var(--red-50); }

.pr-flags { margin-bottom: .9rem; }
.pr-flag-list { list-style: none; margin: 0; padding: 0; display: grid; gap: .4rem; }
.pr-flag-list li { font-size: .88rem; line-height: 1.45; padding: .55rem .8rem; border-radius: 7px; }
.pr-flag-block { background: var(--store-rush-soft); color: var(--red-800); border-left: 4px solid var(--red-700); }
.pr-flag-warn { background: var(--store-rush-soft); color: var(--payroll-orange-2); border-left: 4px solid var(--payroll-orange-3); }
.pr-flag-list em { font-style: normal; font-weight: 600; }

.pr-upload { display: flex; align-items: center; gap: .75rem; flex-wrap: wrap; padding: 1rem; background: var(--gray-50); border: 1px dashed var(--gray-300); border-radius: 9px; }
.pr-file { font-size: .9rem; font-family: inherit; }
.pr-note { font-size: .85rem; color: var(--payroll-gray); }

/* Busy indicator for the packet read. The read takes ~40s, and a greyed-out button with no
   motion reads as BROKEN rather than working — Erik, 2026-08-10, having just been burned by a
   read that genuinely was dead. Motion is the part that says "still alive"; the seconds
   counter is the part that says "and it is making progress".
   🔑 display:inline-flex would BEAT the UA's [hidden]{display:none}, so the attribute alone
   would not hide it — the explicit [hidden] rule is what makes it actually disappear. */
.pr-progress { display: inline-flex; align-items: center; gap: .45rem; font-size: .85rem; font-weight: 600; color: var(--store-ink-soft); }
.pr-progress[hidden] { display: none; }

.pr-spin {
  width: .85em; height: .85em; flex: none;
  border: 2px solid var(--gray-300); border-top-color: var(--brand-800); border-radius: 50%;
  animation: pr-spin .7s linear infinite;
}

@keyframes pr-spin { to { transform: rotate(360deg); } }

/* Still turns, just slowly — a frozen ring next to "reading…" would read as hung. */
@media (prefers-reduced-motion: reduce) { .pr-spin { animation-duration: 2.4s; } }

.pr-btn { background: var(--store-green-100); border: none; color: var(--payroll-green-dark); padding: .55rem 1.1rem; border-radius: 7px; font-weight: 600; font-size: .92rem; cursor: pointer; font-family: inherit; }
.pr-btn:hover:not(:disabled) { background: var(--store-line); }
.pr-btn:disabled { opacity: .5; cursor: not-allowed; }
.pr-btn-primary { background: var(--brand-800); color: var(--color-on-brand); }
.pr-btn-primary:hover:not(:disabled) { background: var(--print-green); }
.pr-btn-ghost { background: transparent; color: var(--payroll-gray); }
.pr-btn-ghost:hover:not(:disabled) { background: var(--store-green-50); }

.pr-review { margin-top: 1.5rem; border-top: 1px solid var(--gray-200); padding-top: 1.25rem; }
.pr-verdict { padding: .8rem 1rem; border-radius: 8px; font-size: .93rem; font-weight: 600; margin-bottom: 1rem; line-height: 1.5; }

/* [hidden]{display:none} is only a UA default — any author display: on these would beat it
   and leave a "hidden" block on screen. Both blocks are toggled by the hidden attribute. */
.pr-review[hidden], .pr-verdict[hidden] { display: none; }
.pr-verdict.is-ok { background: var(--brand-100); color: var(--payroll-green-dark-2); border-left: 4px solid var(--payroll-green); }
.pr-verdict.is-bad { background: var(--store-rush-soft); color: var(--red-800); border-left: 4px solid var(--red-700); }

/* Reconciled, but something on the page is worth a second look before saving — an
   over-drawn balance the report floors at zero, say. Not a failure: Save stays live. */
.pr-verdict.is-warn { background: var(--store-rush-soft); color: var(--payroll-orange-4); border-left: 4px solid var(--payroll-orange-5); }
.pr-verdict ul { margin: .5rem 0 0; padding-left: 1.2rem; font-weight: 400; }

.pr-check-table { max-width: 44rem; }
.pr-ok { color: var(--payroll-green); font-weight: 600; }
.pr-bad { color: var(--red-700); font-weight: 600; }

.pr-commit { display: flex; gap: .6rem; margin-top: 1.25rem; align-items: center; flex-wrap: wrap; }

@media (width <= 720px) {
  .pr-header { flex-direction: column; }
  .pr-search { min-width: 100%; }
  .pr-asof { margin-left: 0; }
}

/* ============================================================
   CUT-APART SLIPS — one per employee, handed out on paper.
   Letter portrait, 0.5in margins → 7.5in x 10in of usable page.
   Grid is 2 cols x 3.333in rows = exactly 6 slips per sheet, so the
   page break lands on a slip boundary instead of slicing one in half.
   ============================================================ */
#print-sheet { display: none; }

@media print {
  /* Only the Print-slips button prints slips. A plain Ctrl+P still prints the
     dashboard, which is what someone expects when they didn't ask for slips. */
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  body.print-slips .pr-wrap { display: none !important; }
  /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
  body.print-slips #print-sheet { display: block !important; }

  @page { size: 8.5in 11in; margin: 0.5in; }
  body.print-slips { background: var(--color-surface); margin: 0; }

  #print-slips-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;

    /* Dashed guides on the outside; each slip draws its own right/bottom edge, so
       adjacent slips share ONE line and every cut is a single scissor pass. */
    border-top: 1px dashed var(--print-line);
    border-left: 1px dashed var(--print-line);
  }

  .slip {
    height: 3.333in;
    border-right: 1px dashed var(--print-line);
    border-bottom: 1px dashed var(--print-line);
    padding: 0.3in 0.32in;
    break-inside: avoid;
    display: flex;
    flex-direction: column;
    color: var(--payroll-gray-dark);

    /* Serif reads as a document rather than a screenshot — this is handed to a person. */
    font-family: Georgia, 'Times New Roman', serif;
  }
  .slip-co { font-size: 8pt; letter-spacing: .06em; text-transform: uppercase; color: var(--gray-700); }
  .slip-name { font-size: 13.5pt; font-weight: 700; margin: .04in 0 .01in; line-height: 1.1; }
  .slip-asof { font-size: 8pt; color: var(--print-ink-soft); margin-bottom: .1in; }

  .slip-rows { border-top: 1.5px solid var(--payroll-gray-dark); padding-top: .05in; }

  /* Vacation and sick both print accrued/used/remaining, so each set is labelled —
     six bare rows would be ambiguous about which balance is which. */
  .slip-group { font-size: 8pt; letter-spacing: .07em; text-transform: uppercase;
                color: var(--print-ink-soft); font-weight: 700; margin: .05in 0 .01in; }

  .slip-row { display: flex; justify-content: space-between; align-items: baseline;
              font-size: 10pt; padding: .028in 0; }
  .slip-row + .slip-row { border-top: 1px solid var(--store-line); }
  .slip-label { color: var(--print-ink); }

  /* Ties the vacation line to the footnote below it. */
  .slip-star { font-weight: 700; margin-left: .04in; }
  .slip-val { font-weight: 700; font-variant-numeric: tabular-nums; }

  /* A negative balance is legitimate here (vacation accrues at one year), so it is
     printed plainly with a note rather than flagged red like an error on screen. */
  .slip-note { font-size: 7.5pt; color: var(--print-ink-soft); margin-top: auto; padding-top: .07in;
               line-height: 1.3; font-style: italic; }
}

/* 2026-09-05 review */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }
.pr-retry { margin-left: .5rem; padding: .3rem .7rem; font-size: .85rem; }
.pr-tab:focus-visible, .pr-btn:focus-visible, .pr-back:focus-visible { outline: 2px solid var(--brand-800); outline-offset: 2px; }
